using TsRecommend;
namespace TsScheduler;
internal sealed class ScheduleGrid : UserControl {
 readonly VScrollBar _vertical=new(){Dock=DockStyle.Right};readonly HScrollBar _horizontal=new(){Dock=DockStyle.Bottom};Size _contentSize;
 public new Point AutoScrollPosition {get=>new(-_horizontal.Value,-_vertical.Value);set{_horizontal.Value=Math.Clamp(Math.Abs(value.X),0,Math.Max(0,_horizontal.Maximum-_horizontal.LargeChange+1));_vertical.Value=Math.Clamp(Math.Abs(value.Y),0,Math.Max(0,_vertical.Maximum-_vertical.LargeChange+1));Invalidate();}}
 public new Size AutoScrollMinSize {get=>_contentSize;set{_contentSize=value;UpdateBars();}}
 void UpdateBars(){if(_vertical==null||_horizontal==null)return;_vertical.LargeChange=Math.Max(1,ClientSize.Height-40);_vertical.SmallChange=45;_vertical.Maximum=Math.Max(0,_contentSize.Height-1);_horizontal.LargeChange=Math.Max(1,ClientSize.Width-30);_horizontal.SmallChange=45;_horizontal.Maximum=Math.Max(0,_contentSize.Width-1);_horizontal.Visible=_contentSize.Width>ClientSize.Width-20;}
 protected override void OnResize(EventArgs e){base.OnResize(e);UpdateBars();Invalidate();}
 protected override void OnMouseWheel(MouseEventArgs e){int next=Math.Clamp(_vertical.Value-e.Delta,0,Math.Max(0,_vertical.Maximum-_vertical.LargeChange+1));_vertical.Value=next;}
 public Action? ViewChanged;
 public List<Show> Shows=[];public Func<string,Color> StationInk=_=>Color.FromArgb(24,54,90);public HashSet<string> Booked=[];public DateTime Day=DateTime.Today;public int VisibleDays=>1;public int DurationMinutes=>1440;public Show? Selected;public Action<Show?,Point>? HoverShow;public Action<Show>? SelectShow;readonly List<(Rectangle Bounds,Show Show)> _hits=[];string? _lastHover;
 int ColumnWidth=>Math.Max(140,(ClientSize.Width-65)/Math.Max(1,Shows.Select(s=>s.Station).Distinct().Count()));
 internal static int TimelineY(double minute)=>40+(int)(minute*3)+Math.Min(2,(int)(minute/480))*30;
 public ScheduleGrid(){DoubleBuffered=true;AutoScroll=false;BackColor=Color.White;Dock=DockStyle.Fill;SetStyle(ControlStyles.ResizeRedraw,true);Controls.Add(_vertical);Controls.Add(_horizontal);_vertical.ValueChanged+=(_,_)=>{ViewChanged?.Invoke();Invalidate();HoverShow?.Invoke(null,Point.Empty);};_horizontal.ValueChanged+=(_,_)=>{ViewChanged?.Invoke();Invalidate();HoverShow?.Invoke(null,Point.Empty);};}
 public void RefreshSchedule(){AutoScrollMinSize=new Size(65+Math.Max(Shows.Select(s=>s.Station).Distinct().Count(),1)*ColumnWidth,TimelineY(1440));Invalidate();}
 internal static Color CategoryFill(Show show){try{var c=ColorTranslator.FromHtml(show.GenreColor);return c.IsEmpty?Color.FromArgb(249,250,252):Color.FromArgb((int)(255*.82+c.R*.18),(int)(255*.82+c.G*.18),(int)(255*.82+c.B*.18));}catch{return Color.FromArgb(249,250,252);}}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;_hits.Clear();var order=new[]{"NHK","日テレ","テレ朝","TBS","テレ東","フジ","Eテレ","MX1"};var stations=Shows.Select(s=>s.Station).Distinct().OrderBy(s=>Array.IndexOf(order,s)<0?99:Array.IndexOf(order,s)).ToArray();int width=ColumnWidth,sx=AutoScrollPosition.X,sy=AutoScrollPosition.Y;var start=new DateTimeOffset(Day.Date,TimeSpan.FromHours(9));using var line=new Pen(Color.FromArgb(214,224,237));
 for(int m=0;m<=1440;m+=30){int y=TimelineY(m)+sy;g.DrawLine(line,65,y,Width,y);}
 for(int col=0;col<stations.Length;col++)foreach(var show in Shows.Where(s=>s.Station==stations[col]&&s.Start<start.AddDays(1)&&s.End>start))for(int segment=0;segment<3;segment++){double from=Math.Max(segment*480,(show.Start-start).TotalMinutes),to=Math.Min((segment+1)*480,(show.End-start).TotalMinutes);if(to<=from)continue;var r=new Rectangle(67+col*width+sx,40+(int)(from*3)+segment*30+sy,width-4,Math.Max(2,(int)((to-from)*3)-1));if(!r.IntersectsWith(ClientRectangle))continue;using var fill=new SolidBrush(CategoryFill(show));g.FillRectangle(fill,r);g.DrawRectangle(line,r);_hits.Add((r,show));if(r.Height>=Font.Height)TextRenderer.DrawText(g,show.Start.ToLocalTime().ToString("HH:mm")+" "+(Booked.Contains(show.Key)?"● ":"")+show.Title,Font,Rectangle.Inflate(r,-5,-3),Color.FromArgb(23,43,65),TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis);if(Selected?.Key==show.Key){using var pen=new Pen(Color.FromArgb(35,91,159),2);g.DrawRectangle(pen,r);}}
 using var axis=new SolidBrush(Color.FromArgb(246,248,251));g.FillRectangle(axis,0,0,65,Height);for(int m=0;m<=1440;m+=60)TextRenderer.DrawText(g,m==1440?"24:00":start.AddMinutes(m).ToString("HH:mm"),Font,new Rectangle(2,TimelineY(m)+sy+2,62,Font.Height),Color.FromArgb(24,44,66),TextFormatFlags.NoPadding);
 using var header=new SolidBrush(Color.FromArgb(229,237,247));for(int segment=0;segment<3;segment++){int y=segment==0?0:40+segment*480*3+(segment-1)*30+sy,height=segment==0?40:30;g.FillRectangle(header,0,y,Width,height);for(int col=0;col<stations.Length;col++)TextRenderer.DrawText(g,stations[col]=="MX1"?"MX":stations[col],Font,new Rectangle(65+col*width+sx,y,width,height),StationInk(stations[col]),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}}
 bool IsHeader(Point p){int y=p.Y-AutoScrollPosition.Y;return p.Y<40||Enumerable.Range(1,2).Any(i=>y>=40+i*480*3+(i-1)*30&&y<70+i*480*3+(i-1)*30);}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);var show=e.X<65||IsHeader(e.Location)?null:_hits.LastOrDefault(h=>h.Bounds.Contains(e.Location)).Show;if(show?.Key!=_lastHover){_lastHover=show?.Key;HoverShow?.Invoke(show,e.Location);}}
 protected override void OnMouseLeave(EventArgs e){base.OnMouseLeave(e);_lastHover=null;HoverShow?.Invoke(null,Point.Empty);}
 protected override void OnMouseClick(MouseEventArgs e){base.OnMouseClick(e);Selected=e.X<65||IsHeader(e.Location)?null:_hits.LastOrDefault(h=>h.Bounds.Contains(e.Location)).Show;if(Selected!=null)SelectShow?.Invoke(Selected);Invalidate();}
}
